with with_gaps as (select *, case when paid_at - lag(paid_at) over (partition by status order by paid_at, id) > interval 7 days then 1 else 0 end as new_group_flag from payments), sessions_payments as (select *, sum(new_group_flag) over (partition by status order by paid_at, id rows between unbounded preceding and current row) as session_id from with_gaps) select id, paid_at, status, new_group_flag, session_id, case when status rlike '^(FAILED|REFUNDED)$' then 'PRIORITY' when status rlike '^(SUCCESS)$' then 'GROUP_A' else 'GROUP_B' end as status_zone from sessions_payments order by new_group_flag desc nulls last;
